int shield_mode(int energy)
{
    int mode;
    int extra;
    if (energy < 30)
    {
        mode = 0;
    }
    else
    {
        if (energy < 70)
        {
            mode = 1;
        }
        else
        {
            mode = 2;
        }
    }
    return mode;
}
